      if (v.type !== "vitals") continue;
      const lp = localParts(v.taken);
      if (!lp) continue;
      const t = ms(v.taken);
      const row: VitalRow = { setting, local_time: `${lp.date}T${lp.time}`, evidence: [{ item_id: d.item.id, entry_id: eid }] };
